dict({
                        async getData(dict: any) {
                            return request('/swagger.json').then((ret: any) => {
                                const res = Object.keys(ret.paths);
                                const data = [];
                                for (const item of res) {
                                    const obj = {label: '', value: ''};
                                    obj.label = item;
                                    obj.value = item;
                                    data.push(obj);
                                }
                                return data;
                            });
                        },
                    })

